from .formatters import rupiah,number,percent
def build_lookup(rows):return {(r['metric'],r['dimension']):float(r['value']) for r in rows}
def render_report(rows,content):
 m=build_lookup(rows);rev=m[('total_revenue','')];elec=m[('category_revenue','Electronics')]
 lines=[f"# {content['title']}",'',f"**Cakupan:** {content['scope']}",'','## Ringkasan Eksekutif',f"- Pendapatan tercatat {rupiah(rev)} dari {number(m[('total_transactions','')])} transaksi.",f"- Nilai transaksi rata-rata adalah {rupiah(m[('aov','')])}; pembeli unik {number(m[('unique_buyers','')])}; pembeli berulang {number(m[('repeat_buyers','')])}.",f"- Electronics menyumbang {percent(elec/rev)} pendapatan pada data uji ini.",'','## Ringkasan Metrik','| Metrik | Nilai | Kunci sumber |','|---|---:|---|',f"| Total transaksi | {number(m[('total_transactions','')])} | total_transactions |",f"| Total pendapatan | {rupiah(rev)} | total_revenue |",f"| Nilai transaksi rata-rata | {rupiah(m[('aov','')])} | aov |",f"| Pembeli unik | {number(m[('unique_buyers','')])} | unique_buyers |",f"| Pembeli berulang | {number(m[('repeat_buyers','')])} | repeat_buyers |",f"| Porsi Electronics | {percent(elec/rev)} | category_revenue/Electronics |",f"| Pendapatan kota Unknown | {rupiah(m[('city_revenue','Unknown')])} | city_revenue/Unknown |",'','## Temuan']
 for i,x in enumerate(content['insights'],1):lines += [f"### {i}. {x['title']}",f"- **Bukti:** {x['evidence']}",f"- **Makna:** {x['meaning']}",f"- **Tindakan:** {x['action']}",f"- **Batasan:** {x['boundary']}",'']
 lines += ['## Asumsi']+[f'- {x}' for x in content['assumptions']]+['','## Batasan']+[f'- {x}' for x in content['limitations']]+['','## Langkah Berikutnya']+[f'- {x}' for x in content['next_steps']]+['','## Ketertelusuran','Dihasilkan dari `data/input/metrics.csv`. Kunci metrik terhubung ke berkas SQL Sesi 4. Perintah tercantum dalam `EXECUTION_RUNBOOK.md`.','']
 return '\n'.join(lines)
